using System.Collections.Generic;
using UnityEngine;

namespace AdventureKing.Gameplay
{
    /// <summary>
    /// Item pictures come ONLY from sprites that exist in Assets: the owner's per-item icon / worldSprite in Resources/ItemVisuals.asset (empty until filled),
    /// then the shared icon of the item's kind (Resources/ItemIcons/{iconKey}, e.g. item_junk). Nothing is generated by code.
    /// </summary>
    public static class ItemIconBook
    {
        private static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();
        private static ItemVisualDatabase db;

        public static ItemVisualDatabase Database { get { if (!db) db = Resources.Load<ItemVisualDatabase>("ItemVisuals"); return db; } }

        /// <summary>The bag / shop icon: the item's own, else the shared key icon, else null (callers hide the Image).</summary>
        public static Sprite For(string itemId, string iconKey = null)
        {
            Sprite s = Own(itemId, world: false);
            return s ? s : Shared(iconKey);
        }

        /// <summary>The sprite of a drop on the ground: worldSprite, else the icon, else the shared key icon.</summary>
        public static Sprite WorldSprite(string itemId, string iconKey = null)
        {
            Sprite s = Own(itemId, world: true);
            return s ? s : Shared(iconKey);
        }

        private static Sprite Own(string itemId, bool world)
        {
            ItemVisual v = Database ? Database.Item(itemId) : null;
            if (v == null) return null;
            return world && v.worldSprite ? v.worldSprite : v.icon ? v.icon : v.worldSprite;
        }

        /// <summary>Resources/ItemIcons/{name}: the shared pictures that already exist in the project.</summary>
        public static Sprite Shared(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            if (cache.TryGetValue(name, out Sprite s) && s) return s;
            s = Resources.Load<Sprite>("ItemIcons/" + name);
            cache[name] = s;
            return s;
        }

        /// <summary>Legacy name: the owner's sprite for this id, else the shared one.</summary>
        public static Sprite Load(string name) { Sprite s = Own(name, false); return s ? s : Shared(name); }

        /// <summary>Gold on the ground: the owner's coin / pile / bag sprite by amount (ItemVisuals ids coin_small / coin_medium / coin_bag); null = the caller's default coin.</summary>
        public static Sprite Coins(long amount) => Own(amount >= 60 ? "coin_bag" : amount >= 15 ? "coin_medium" : "coin_small", world: true);
    }
}
